props.css:
@keyframes _wtp_slide_lottie {
  from { transform: translate3d(0px, 0px, 0px); }
  to { transform: translate3d(0px, -5vh, 0px); }
}

@keyframes _wtp_slide_top {
  from { transform: translate3d(0px, 15vh, 0px); }
  to { transform: translate3d(0px, -28vh, 0px); }
}

@keyframes _wtp_slide_bottom {
  from { transform: translate3d(0px, 28vh, 0px); }
  to { transform: translate3d(0px, -24vh, 0px); }
}

@keyframes _wtp_slide_logo {
  from { transform: translate3d(0px, 0px, 0px) }
  to { transform: translate3d(0px, -24vh, 0px) }
}

@keyframes _wtp_fade {
  from { opacity: 1; }
  to { opacity: 0; }
}

.block._wtp__top,
.block._wtp__bottom,
.block._wtp__logo,
.block._wtpGuide {
  animation-delay: 2.5s;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-duration: 1.2s;
  transition: none;
}

.block._wtp__top {
  transform: translate3d(0px, 15vh, 0px); 
  animation-name: _wtp_slide_top;
  animation-fill-mode: forwards;
  z-index: 10;
}

.block._wtp__logo {
  animation-name: _wtp_slide_logo, _wtp_fade;
  animation-fill-mode: forwards;
  animation-timing-function: ease-in, cubic-bezier(0.55,0.06,0.68,0.19);
  animation-duration: 0.9s;
  z-index: 1;
}

.block._wtp__bottom {
  animation-name: _wtp_slide_bottom, _wtp_fade;
  animation-direction: normal, reverse;
  animation-fill-mode: forwards;
  opacity: 0;
}

.block._wtp__buttons {
    margin-top: calc(var(--space)* 8);
}

.block._wtpGuide {
  padding: var(--marginV) var(--marginH);
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: stretch;
}

.block._wtpGuide__item {
  display: flex;
  flex-direction: row;
  justify-content: stretch;
  align-items: center;
  padding: 16px;
  background: #ffffff;
}

.block._wtpGuide__item:last-child {
    border-radius: 0 0 12px 12px;
}

.block._wtpGuide__item:first-child {
    border-radius: 12px 12px 0 0;
}

.block._wtpGuide__check {
  display: flex;
  flex-grow: 0;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin: 0;
  border: 1px solid rgba(0, 0, 0, 0.6);
  border-radius: 20px;
}

.block._wtpGuide__check_filled {
  border-color: #12a252;
  background-color: #12a252;
}

.block._wtpGuide__check_filled img {
  filter: invert(100%);
}

.block._wtpGuide__content {
  margin-left: 16px;
  align-items: flex-start;
  justify-content: center;
  flex-direction: column;
  display: flex;
  flex-grow: 1;
  flex-shrink: 1;
  align-items: flex-start;
}

.block._wtpGuide__title {
  padding: 0;
  margin: 0;
  text-transform: uppercase;
  font-style: normal;
  font-weight: 400;
  font-size: 11px;
  line-height: 16px;
  letter-spacing: 0.006em;
  color: #000000;
  text-align: left;
}

.block._wtpGuide__subtitle {
  padding: 0;
  margin: 0;
  font-style: normal;
  font-weight: 400;
  font-size: 16px;
  line-height: 24px;
  letter-spacing: -0.02em;
  color: #000000;
  text-align: left;
}

.block._wtp__loader {
  margin: 8px 0 16px;
  padding: 0;
  height: 44px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  width: auto;
}

.block._wtpLoader__text {
  font-weight: 600;
  font-size: 18px;
  color: #ffffff;
}

.block._wtpLoader__lottie {
  width: 30px;
  height: 30px;
  margin: 4px -6px 0 0px;
}

[class*="blockLottie_confettiTop--"] {
  pointer-events: none;
  z-index: 5;
  animation-name: _wtp_slide_lottie;
  animation-direction: normal;
  animation-fill-mode: forwards;
}

._wtp__bottom {
  opacity: unset;
}

@keyframes fadeIn {
  0% { opacity: 0; }
  100% { opacity: 100%; }
}

@keyframes backgroundHorizontalSlide {
  0% {
    background-position: left;
  }
  100% {
    background-position: right;
  }
}
